import * as THREE from 'three';

// Deterministic PRNG (mulberry32)
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const MAX_LEAN = 0.25;

/**
 * Build an instanced grass field.
 *
 * @param {object} [options]
 * @param {number} [options.blades=5000]   Number of grass blades (instances).
 * @param {number} [options.area=20]       Side length of the square area.
 * @param {number} [options.seed=1]        Seed for the PRNG.
 * @returns {{ geometry: THREE.BufferGeometry, material: THREE.Material, mesh: THREE.InstancedMesh }}
 */
export function buildGrass({ blades = 5000, area = 20, seed = 1 } = {}) {
  const rand = mulberry32(seed);

  // A single blade: two crossed quads (4 triangles), standing on y = 0.
  const halfW = 0.05;
  const height = 1;
  const positions = new Float32Array([
    // Quad 1 (in XZ... actually XY plane, facing +Z)
    -halfW, 0, 0,
    halfW, 0, 0,
    halfW, height, 0,
    -halfW, height, 0,
    // Quad 2 (crossed, in the YZ-ish plane rotated 90 degrees)
    0, 0, -halfW,
    0, 0, halfW,
    0, height, halfW,
    0, height, -halfW,
  ]);
  const indices = [
    0, 1, 2, 0, 2, 3, // quad 1
    4, 5, 6, 4, 6, 7, // quad 2
  ];

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();

  const count = blades;

  // Seeded per-instance transforms.
  const mesh = new THREE.InstancedMesh(
    geometry,
    new THREE.MeshLambertMaterial({ color: 0x3a7d2c, side: THREE.DoubleSide }),
    count
  );

  const matrix = new THREE.Matrix4();
  const half = area / 2;
  for (let i = 0; i < count; i++) {
    const x = rand() * area - half;
    const z = rand() * area - half;
    const s = 0.7 + rand() * 0.6; // uniform scale in [0.7, 1.3]
    matrix.makeScale(s, s, s);
    matrix.setPosition(x, 0, z);
    mesh.setMatrixAt(i, matrix);
  }
  mesh.instanceMatrix.needsUpdate = true;

  // Per-blade wind phase attribute.
  const phases = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    phases[i] = rand() * Math.PI * 2;
  }
  geometry.setAttribute('windPhase', new THREE.InstancedBufferAttribute(phases, 1));

  return { geometry, material: mesh.material, mesh };
}

/**
 * Wind lean angle for instance `i` at time `t`:
 * maxLean * sin(t + phase_i), with maxLean = 0.25 and phase read
 * from the geometry's "windPhase" attribute.
 */
export function windAngleAt(mesh, i, t) {
  const phase = mesh.geometry.getAttribute('windPhase').getX(i);
  return MAX_LEAN * Math.sin(t + phase);
}

