import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildGrass, windAngleAt } from '../src/grass.js';

describe('grass field', () => {
  const { mesh } = buildGrass({ blades: 1234, area: 20, seed: 42 });

  it('has the requested instance count', () => {
    expect(mesh.count).toBe(1234);
    expect(mesh.instanceMatrix.count).toBe(1234);
  });

  it('has a windPhase attribute with count = blades and values in [0, 2PI)', () => {
    const attr = mesh.geometry.getAttribute('windPhase');
    expect(attr).toBeDefined();
    expect(attr.itemSize).toBe(1);
    expect(attr.count).toBe(1234);
    for (let i = 0; i < attr.count; i++) {
      const v = attr.getX(i);
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(Math.PI * 2);
    }
  });

  it('windAngleAt matches hand computation for known indices', () => {
    const attr = mesh.geometry.getAttribute('windPhase');
    const indices = [0, 567, 1233];
    for (const i of indices) {
      const phase = attr.getX(i);
      const t = 1.234;
      const expected = 0.25 * Math.sin(t + phase);
      const got = windAngleAt(mesh, i, t);
      expect(got).toBeCloseTo(expected, 12);
    }
    // sanity: differs from a wrong phase
    expect(windAngleAt(mesh, 0, 1.234)).not.toBeCloseTo(
      0.25 * Math.sin(1.234 + attr.getX(1)),
      12
    );
  });

  it('decomposes instance positions inside the area', () => {
    const m = new THREE.Matrix4();
    const pos = new THREE.Vector3();
    for (let i = 0; i < mesh.count; i++) {
      mesh.getMatrixAt(i, m);
      pos.setFromMatrixPosition(m);
      expect(pos.x).toBeGreaterThanOrEqual(-10);
      expect(pos.x).toBeLessThanOrEqual(10);
      expect(pos.z).toBeGreaterThanOrEqual(-10);
      expect(pos.z).toBeLessThanOrEqual(10);
    }
  });

  it('is deterministic per seed (matrices and phases)', () => {
    const opts = { blades: 300, area: 8, seed: 7 };
    const a = buildGrass(opts);
    const b = buildGrass(opts);

    const ma = new THREE.Matrix4();
    const mb = new THREE.Matrix4();
    for (let i = 0; i < a.mesh.count; i++) {
      a.mesh.getMatrixAt(i, ma);
      b.mesh.getMatrixAt(i, mb);
      expect(ma.equals(mb)).toBe(true);
    }

    const pa = a.mesh.geometry.getAttribute('windPhase');
    const pb = b.mesh.geometry.getAttribute('windPhase');
    for (let i = 0; i < pa.count; i++) {
      expect(pa.getX(i)).toBe(pb.getX(i));
    }

    // different seed -> different data
    const c = buildGrass({ ...opts, seed: 8 });
    let differs = false;
    const pc = c.mesh.geometry.getAttribute('windPhase');
    for (let i = 0; i < pa.count && !differs; i++) {
      if (pa.getX(i) !== pc.getX(i)) differs = true;
    }
    expect(differs).toBe(true);
  });
});

